// === Tab: mySketch ===
//Forest used is from Ivan Rudnicki - Smoky Forest -https://openprocessing.org/sketch/1737427
//Music byDenys Brodovskyi from Pixabay - https://pixabay.com/music/future-bass-tell-me-the-truth-260010/
//Previous bird used in this sketch was removed - apparently it stopped loading mysteriouly. 
//New bird Designed by FreePic - https://www.freepik.com/free-vector/flat-design-animation-frames-element-collection_31630031.htm#fromView=keyword&page=1&position=0&uuid=96d4311a-2b74-45d4-9a0f-fe9ba919f22b&query=Bird+Sprite

let bg, air;
let panels = [];
let xshift = 0;
let yshift = 0;
let haze = true;
let photo=[]
let overlay
function preload() {
	song = loadSound("https://openprocessing.org/sketch/2643284/files/tell-me-the-truth-260010.mp3")
	for( j=0; j<5; j++){
    photo[j] = loadImage("https://openprocessing.org/sketch/2643284/files/bird-" + nf(j) + ".png");
  }
}

function setup() {
	createCanvas(windowWidth, windowHeight);
	imageMode(CENTER);
	overlay = createGraphics(2 * width, 1.5 * height);
	bg = createGraphics(2 * width, 1.5 * height);
	air = createGraphics(2 * width, 1.5 * height);
	for (let i = 0; i < 6; i++) {
		panels.push(createGraphics(width+900,height+400)); //x pos panel length
	}

	noiseDetail(2);
	let start1 = color(255, 140, 0, 200);
	let finish = color(0, 0, 0, 200);
	drawSky(bg, start1, finish);
	start1 = color(255, 140, 0, 130);
	finish = color(255, 255, 255, 50);
	drawSky(air, start1, finish);
	makeEverything();

	fft = new p5.FFT();
  fft.setInput(song);	
	song.play()
	song.loop()
}

function makeEverything() {
	noiseSeed(random(1000));
	let y = 2 * height / 3;
	for (let p of panels) {
		drawGround(y, p);
		y += height / 12
	}
}

let counter=0
let B = 0
let lM = 0
let M = 0
let hM = 0
let T = 0
let count=0

function draw() 
{
	counter=counter-5
	background(T,lM);
	//let txshift = ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - width / 2) / 6;
	//xshift = lerp(xshift, txshift, 0.05);
	//let tyshift = ((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - height / 2) / 20;
	//yshift = lerp(yshift, tyshift, 0.05);
	//image(bg, width / 2  + counter, height / 2 );
	for (let i = 1; i < 7; i++) 
	{
		image(panels[i - 1], B+counter*i/5+ width / 2 + i * 90, (height / 2 + i * 5)+(T/4)+(B));

	}
	if (haze) image(air, width / 2, height / 2);


	let spectrum = fft.analyze();
	let bass, lowMid, mid, highMid, treble; 

	bass = fft.getEnergy("bass");
	lowMid = fft.getEnergy("lowMid");
	mid = fft.getEnergy("mid");
	highMid = fft.getEnergy("highMid");
	treble = fft.getEnergy("treble");

	 B = round(map(bass, 0, 300, -200, 200, true))
	 lM = round(map(lowMid, 0, 100, 0, 255, true))
	 M = round(map(mid, 0, 300, 0, 255, true))
	 hM = round(map(highMid, 0, 100, -100, 100, true))
	 T = round(map(treble, 0, 300, 15, 255, true))

		if (frameCount>130)
		{
			count++;
			if(count >= photo.length) count = 0;
			push()
				if(frameRate()>55) scale(random(4))
				else scale(1)
				image(photo[int(count)], width/2, (height/2), 100,100);
			pop()
		frameRate(T/3);
	}
	let num=T-68
	let choice=round(random(0,5))
	if(choice==0) fill(255, 110, 199,num)
	if(choice==1) fill(0, 255, 255,num)
	if(choice==2) fill(57, 255, 20,num)
	if(choice==3) fill(191, 0, 255,num)
	if(choice==4) fill(255, 95, 31,num)
	if(choice==5) fill(255, 255, 51,num)
	rect(0,0,20000,height)
}

function drawSky(cg, start1, finish) {
	cg.clear();
	let c = start1;
	for (let y = 0; y <= cg.height; y += 2) {
		c = lerpColor(start1, finish, y / (cg.height / 2));
		cg.stroke(c);
		cg.strokeWeight(2);
		cg.noFill();
		cg.line(0, y, cg.width, y);
	}
	noStroke();
}

function drawGround(startY, panel) {
	let a = map(startY, 2 * height / 3, height * 1.3, 20, 200);
	panel.stroke(0, a);
	panel.strokeWeight(a / 20);
	panel.fill(0, a);
	let freq = map(startY, 2 * height / 3, 1.5 * height, 10, 200);
	panel.beginShape();
	panel.curveVertex(-50, panel.height);
	panel.curveVertex(-50, panel.height);
	panel.curveVertex(-50, startY);
	panel.curveVertex(-50, startY);
	for (let x = -50; x <= panel.width + 50; x += random(width / 500, width / 300)) {
		let y1 = startY - (height / 5) * noise(startY + x / 350);
		let w = y1 * y1 / (height * random(10, 20));
		let y2 = startY - (height / 5) * noise(startY + (x + w) / 350);
		if (floor(random(freq)) == 0) {
			drawTree(x + w / 2, y1, y2, w, -50, 30, panel);
			x += 1.5 * w;
		} else {
			panel.curveVertex(x, y1);
		}
	}
	panel.curveVertex(panel.width + 50, startY);
	panel.curveVertex(panel.width + 50, startY);
	panel.curveVertex(panel.width + 50, panel.height);
	panel.curveVertex(panel.width + 50, panel.height);
	panel.endShape(CLOSE);
}

function drawTree(x, y1, y2, w, t, a, panel) {
	for (let y = y1; y > t; y -= 10) {
		panel.curveVertex(x - (w / 2) * noise(y1 + 50 * x + y / 250), y);
		if (y < y1 / 1.5 && floor(random(18)) == 0) {
			panel.push();
			panel.noStroke();
			panel.ellipse(x + random(w / 4), y, w / 3, random(w / 3, w / 1.5));
			panel.pop();
		}
	}
	for (let y = t; y <= y2; y += 10) {
		panel.curveVertex((x + w) - (w / 2) * noise(y1 + 50 * x + y / 250), y);
	}
}

function mousePressed() {
	fullscreen(true)
	for (let p of panels) {
		p.clear();
	}
	bg.clear();
	air.clear();
	var start1 = color(random(50, 185), random(50, 185), random(50, 185), 200);
	var finish = color(0, 0, 0, 200);
	drawSky(bg, start1, finish);
	start1.setAlpha(130);
	finish = color(255, 255, 255, 30);
	drawSky(air, start1, finish);
	makeEverything();
}

function keyPressed() {
	if (keyCode == 72) haze = !haze;
}

